INV_CONTENT = "#!/usr/bin/env python3\n\"\"\"invariants.py \u2014 Garde-fou pre-commit pour gtamapdata/. Exit 1 si violation.\n\nNe le contourne JAMAIS: chaque famille de bug d'aujourd'hui (2026-06-10) aurait\nete pognee ici \u2014 poses fantomes (ecrit != simule), violations z ecrites en\nbypassant update_landmark, leaks bougees par un solve trop confiant.\n\nCHECKS:\n  1. Z-CONSTRAINTS: tout LM avec z_constraint fixed a xyz[2] == value sur\n     disque (doctrine \"single source of truth\", retablie session du soir).\n  2. LEAKS IMMOBILES: toute cam HUD-locked (is_triangulation_trusted) a une\n     pose identique a la reference gelee tools/audit/leak_poses_ref.json.\n     Apres un intake T3 legitime qui AJOUTE des leaks: --freeze pour regeler.\n     Une leak qui BOUGE n'est jamais legitime.\n  3. SCHEMA: cameras (xyz3/ypr3/fov2/size2), landmarks (xyz None|3),\n     pixels -> cams existantes, source_cameras -> cams existantes.\n\nUsage:\n    python3 tools/audit/invariants.py            # check, exit 1 si echec\n    python3 tools/audit/invariants.py --freeze   # (re)gele la reference leaks\nConvention: rouler AVANT chaque `git commit` qui touche gtamapdata/.\n\"\"\"\nimport argparse, json, os, sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nsys.path.insert(0, ROOT)\nimport gtamapdata as md\nsys.path.insert(0, os.path.join(ROOT, \"tools\"))\nfrom leak_cam_audit import is_triangulation_trusted\n\nREF_PATH = os.path.join(ROOT, \"tools\", \"audit\", \"leak_poses_ref.json\")\nEPS = 1e-6\n\n\ndef locked_cams():\n    return sorted(n for n in md.cameras if is_triangulation_trusted(n, cameras=md.cameras))\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--freeze\", action=\"store_true\",\n                    help=\"(re)gele la reference des poses leaks depuis l'etat actuel\")\n    ap.add_argument(\"--strict\", action=\"store_true\",\n                    help=\"les WARN (dette legacy, ex: provenance orpheline) deviennent des FAIL\")\n    args = ap.parse_args()\n\n    if args.freeze:\n        ref = {n: {\"xyz\": md.cameras[n][\"xyz\"], \"ypr\": md.cameras[n][\"ypr\"],\n                   \"fov\": md.cameras[n][\"fov\"]} for n in locked_cams()}\n        with open(REF_PATH, \"w\") as f:\n            json.dump(ref, f, indent=1, sort_keys=True)\n        print(f\"FROZEN: {len(ref)} poses leaks -> {REF_PATH} (a committer)\")\n        return 0\n\n    fails = []\n    warns = []\n\n    def is_provenance_marker(s_):\n        # \"(geometric: ...)\" et les marqueurs TOUT_EN_MAJUSCULES (ex:\n        # CONSTRUCTED_FINAL_FIT du rebuild Portofino) ne sont pas des cams.\n        return s_.startswith(\"(\") or (s_.replace(\"_\", \"\").isupper() and \"_\" in s_)\n\n    # \u2500\u2500 1. z_constraints coherentes sur disque \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    for n, m in md.landmarks_meta.items():\n        zc = (m or {}).get(\"z_constraint\")\n        if zc and zc.get(\"type\") == \"fixed\" and md.landmarks.get(n) is not None:\n            if abs(md.landmarks[n][2] - float(zc[\"value\"])) > EPS:\n                fails.append(f\"Z-CONSTRAINT: {n} z={md.landmarks[n][2]:+.3f} != {zc['value']}\")\n\n    # \u2500\u2500 2. leaks immobiles vs reference gelee \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    if not os.path.exists(REF_PATH):\n        fails.append(f\"LEAK-REF: {REF_PATH} absent \u2014 roule --freeze une premiere fois\")\n    else:\n        with open(REF_PATH) as f:\n            ref = json.load(f)\n        cur = set(locked_cams())\n        for n, r in ref.items():\n            if n not in md.cameras:\n                fails.append(f\"LEAK: {n} dans la ref mais absente de cameras.json\")\n                continue\n            c = md.cameras[n]\n            for k in (\"xyz\", \"ypr\", \"fov\"):\n                a, b = c.get(k), r.get(k)\n                if a is None or b is None:\n                    if a != b:\n                        fails.append(f\"LEAK: {n}.{k} {b} -> {a}\")\n                    continue\n                if any((x is None) != (y is None) or\n                       (x is not None and abs(float(x) - float(y)) > EPS)\n                       for x, y in zip(a, b)):\n                    fails.append(f\"LEAK: {n}.{k} a bouge: {b} -> {a}\")\n        new_leaks = cur - set(ref)\n        if new_leaks:\n            print(f\"NOTE: {len(new_leaks)} nouvelles cams HUD-locked pas dans la ref \"\n                  f\"(normal apres intake; --freeze pour les geler): {sorted(new_leaks)[:5]}...\")\n\n    # \u2500\u2500 3. schema \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    for n, c in md.cameras.items():\n        for k, ln in ((\"xyz\", 3), (\"ypr\", 3), (\"fov\", 2), (\"size\", 2)):\n            v = c.get(k)\n            if not isinstance(v, (list, tuple)) or len(v) != ln:\n                fails.append(f\"SCHEMA cam {n}.{k}: {v!r}\")\n    for n in md.landmarks:\n        v = md.landmarks[n]\n        if v is not None and (not hasattr(v, \"__len__\") or len(v) != 3):\n            fails.append(f\"SCHEMA lm {n}.xyz: {v!r}\")\n        srcs = (md.landmarks_meta.get(n) or {}).get(\"source_cameras\") or []\n        for s in srcs:\n            if not is_provenance_marker(s) and s not in md.cameras:\n                warns.append(f\"PROVENANCE lm {n}: source_camera orpheline '{s}' \"\n                             \"(rename/suppression historique \u2014 la protection FIXED \"\n                             \"ne s'applique plus a cette source)\")\n    for cn in md.pixels:\n        if cn not in md.cameras:\n            warns.append(f\"PROVENANCE pixels: cam orpheline '{cn}' \"\n                         f\"({len(md.pixels[cn])} markings morts \u2014 TODO: remap vers la \"\n                         \"cam renommee ou purger)\")\n\n    if warns:\n        print(f\"WARNINGS: {len(warns)} (dette legacy, --strict pour en faire des FAIL)\")\n        for w in warns[:8]:\n            print(\"  WARN\", w)\n        if len(warns) > 8:\n            print(f\"  ... +{len(warns)-8}\")\n        if args.strict:\n            fails.extend(warns)\n\n    n_zc = sum(1 for m in md.landmarks_meta.values() if (m or {}).get(\"z_constraint\"))\n    if fails:\n        print(f\"INVARIANTS: {len(fails)} VIOLATION(S)\")\n        for f_ in fails[:30]:\n            print(\"  FAIL\", f_)\n        if len(fails) > 30:\n            print(f\"  ... +{len(fails)-30}\")\n        return 1\n    print(f\"INVARIANTS OK \u2014 z_constraints={n_zc}, leaks_ref={len(json.load(open(REF_PATH))) if os.path.exists(REF_PATH) else 0}, \"\n          f\"cams={len(md.cameras)}, lms={len(md.landmarks)}\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"
FZC_CONTENT = "#!/usr/bin/env python3\n\"\"\"\nfind_z_candidates.py \u2014 Scan landmarks.json pour proposer des candidats \u00e0\ncontraindre \u00e0 z=0 (coastal points, pins, marina, beach, etc.).\n\nHeuristic :\n  - |z| < threshold (default 1.0m) ET\n  - name match COASTAL_PATTERNS OU zone in COASTAL_ZONES\n\nOutput :\n  - Table \u00e0 reviewer dans le terminal\n  - JSON dans /tmp/z_candidates.json \u00e0 passer \u00e0 apply_z_constraints.py\n\nRun from gtamaplib-main/ :\n    python3 tools/audit/find_z_candidates.py\n    python3 tools/audit/find_z_candidates.py --z-threshold 0.5\n    python3 tools/audit/find_z_candidates.py --include-all-near-zero\n\"\"\"\nimport argparse\nimport json\nimport os\nimport re\nimport sys\n\nGTAMAP_DIR = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nsys.path.insert(0, GTAMAP_DIR)\nimport gtamapdata as md\n\nOUTPUT_PATH = '/tmp/z_candidates.json'\n\n# Patterns dans les noms qui sugg\u00e8rent un objet au niveau du sol/eau.\n# NOTE : `Pin` exclu volontairement \u2014 les `Pin AXX/BXX/CXX/DXX` sont des\n# shipping lane pins triangul\u00e9s depuis les cams Keys (LEAK) et ont z=2-4m,\n# pas z=0. Si on ajoute des \"marina pins\" plus tard, utilise un nom plus\n# explicite (ex: \"Marina Pin\").\n# DOCTRINE WATERLINE (2026-06-10, tools/audit/keys_z_bias_analysis.py):\n# la ligne d'eau VISIBLE dans les frames n'est PAS le datum z=0 du moteur\n# (mediane Keys -1.30m, leak Ocean near Keys (E) a -0.60m). z=0 s'applique\n# UNIQUEMENT aux structures construites plates. Les features naturelles et\n# les objets flottants (Boat, Buoy: marees!) sont EXCLUS d'office.\nCOASTAL_PATTERNS = re.compile(\n    r'\\b('\n    r'Marina|Pier|Dock|Jetty|Boardwalk|Wharf|Quay|'\n    r'Harbor|Harbour|Seawall|Pool'\n    r')\\b',\n    re.IGNORECASE\n)\n\n# Exclusion doctrine: jamais candidats, meme avec --include-all-near-zero\nNATURAL_WATERLINE_PATTERNS = re.compile(\n    r'\\b('\n    r'Island|Key|Bay|Beach|Coast|Shore|Shoreline|Lagoon|Inlet|Cove|'\n    r'Mangrove|Surf|Ocean|Reef|Sandbar|Boat|Buoy'\n    r')\\b',\n    re.IGNORECASE\n)\n\n# Plus de regle zone-wide: c'est elle qui a cree les constraints d'iles\n# retirees le 2026-06-10 (tout LM |z|<1 des Keys devenait candidat).\nCOASTAL_ZONES = set()\n\nparser = argparse.ArgumentParser()\nparser.add_argument('--z-threshold', type=float, default=1.0,\n                    help='Max |z| pour \u00eatre consid\u00e9r\u00e9 comme candidat (default: 1.0m)')\nparser.add_argument('--include-all-near-zero', action='store_true',\n                    help='Inclure TOUS les landmarks avec |z| < threshold, '\n                         'sans filtrer par name/zone (plus large, plus de faux positifs)')\nparser.add_argument('--output', default=OUTPUT_PATH,\n                    help=f'Path du JSON output (default: {OUTPUT_PATH})')\nargs = parser.parse_args()\n\n\ndef is_already_constrained(meta):\n    \"\"\"A d\u00e9j\u00e0 un z_constraint set.\"\"\"\n    return bool(meta.get('z_constraint'))\n\n\ndef matches_coastal_name(name):\n    return bool(COASTAL_PATTERNS.search(name))\n\n\ndef is_in_coastal_zone(meta):\n    return meta.get('zone') in COASTAL_ZONES\n\n\n# \u2500\u2500 Scan \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ncandidates = []\nalready_constrained = []\nexcluded_doctrine = []\nnear_zero_skipped = []\n\nfor lm_name, xyz in md.landmarks.items():\n    if xyz is None:\n        continue\n    z = float(xyz[2])\n    if abs(z) >= args.z_threshold:\n        continue\n\n    meta = md.landmarks_meta.get(lm_name, {})\n\n    if is_already_constrained(meta):\n        already_constrained.append((lm_name, z, meta['z_constraint']))\n        continue\n\n    # Exclusion doctrine: rivages/iles/objets flottants ne sont JAMAIS\n    # candidats z=0, meme avec --include-all-near-zero.\n    if NATURAL_WATERLINE_PATTERNS.search(lm_name):\n        excluded_doctrine.append((lm_name, z))\n        continue\n\n    name_match = matches_coastal_name(lm_name)\n    zone_match = is_in_coastal_zone(meta)\n\n    if args.include_all_near_zero or name_match or zone_match:\n        reasons = []\n        if name_match: reasons.append('name')\n        if zone_match: reasons.append('zone')\n        if not reasons: reasons.append('near-zero')\n        candidates.append({\n            'lm': lm_name,\n            'current_z': z,\n            'zone': meta.get('zone'),\n            'sources': meta.get('source_cameras', []),\n            'reasons': reasons,\n        })\n    else:\n        near_zero_skipped.append((lm_name, z, meta.get('zone')))\n\n\n# \u2500\u2500 Print report \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nprint(f\"Scan landmarks.json (|z| < {args.z_threshold}m, \"\n      f\"{'ALL near-zero' if args.include_all_near_zero else 'coastal name/zone match'})\")\nprint()\nif excluded_doctrine:\n    print(f\"{len(excluded_doctrine)} exclus par doctrine waterline (rivages/flottants, jamais z=0):\")\n    for n_, z_ in excluded_doctrine[:10]:\n        print(f\"    {z_:+6.2f}m  {n_}\")\n    if len(excluded_doctrine) > 10:\n        print(f\"    ... +{len(excluded_doctrine)-10}\")\n    print()\n\nprint(f\"Total landmarks scanned : {sum(1 for v in md.landmarks.values() if v is not None)}\")\nprint(f\"  Already z-constrained : {len(already_constrained)}\")\nprint(f\"  Candidats propos\u00e9s    : {len(candidates)}\")\nprint(f\"  Near-zero non matched : {len(near_zero_skipped)} \"\n      f\"(re-run avec --include-all-near-zero pour les voir)\")\nprint()\n\nif candidates:\n    print(\"\u2500\" * 100)\n    print(f\"  {'#':>3}  {'landmark':<45}  {'z':>7}  {'zone':<14}  reasons\")\n    print(\"\u2500\" * 100)\n    candidates.sort(key=lambda c: (c['zone'] or '', c['lm']))\n    for i, c in enumerate(candidates, 1):\n        reasons_str = '+'.join(c['reasons'])\n        print(f\"  {i:>3}  {c['lm'][:45]:<45}  {c['current_z']:>+6.2f}m  \"\n              f\"{(c['zone'] or '?')[:14]:<14}  {reasons_str}\")\n    print()\n\nif already_constrained:\n    print(f\"\u2298 Already z-constrained ({len(already_constrained)}, skipped):\")\n    for lm, z, zc in already_constrained[:10]:\n        zc_str = f\"{zc.get('type')}={zc.get('value')}\" if zc else 'unknown'\n        print(f\"    {lm[:40]:<40}  z={z:+.2f}m  ({zc_str})\")\n    if len(already_constrained) > 10:\n        print(f\"    ... +{len(already_constrained) - 10} more\")\n    print()\n\n# \u2500\u2500 Write JSON \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nif candidates:\n    with open(args.output, 'w') as f:\n        json.dump({\n            'candidates': candidates,\n            'meta': {\n                'z_threshold': args.z_threshold,\n                'include_all_near_zero': args.include_all_near_zero,\n                'proposed_constraint': {'type': 'fixed', 'value': 0.0},\n            }\n        }, f, indent=2)\n    print(f\"Wrote {args.output}\")\n    print()\n    print(\"Next steps :\")\n    print(f\"  1. Review {args.output} et enlever les faux positifs si besoin :\")\n    print(f\"     # ex: ouvrir avec ton \u00e9diteur, supprimer les entries ind\u00e9sirables\")\n    print()\n    print(f\"  2. Apply :\")\n    print(f\"     python3 tools/refine/apply_z_constraints.py\")\n    print(f\"     python3 tools/refine/apply_z_constraints.py --apply\")\nelse:\n    print(\"Aucun candidat trouv\u00e9. Essaie --include-all-near-zero ou un --z-threshold plus grand.\")\n"

